<?php
namespace App\Http\Controllers\Api\V1;
use App\Models\{Company,Customer,Project,ProjectTask,ProjectTimesheet,Employee}; use App\Services\{AuthorizationService,OptionalModuleService}; use App\Support\TenantContext; use Illuminate\Http\Request;
final class ProjectController { public function index(OptionalModuleService $m){$m->require('projects');return response()->json(['data'=>Project::where('tenant_id',app(TenantContext::class)->id())->with('tasks')->paginate(25)]);} public function store(Request $r,OptionalModuleService $m,AuthorizationService $a){$m->require('projects');$t=app(TenantContext::class)->id();$d=$r->validate(['company_id'=>'required|uuid','customer_id'=>'nullable|uuid','manager_id'=>'nullable|uuid','code'=>'required|alpha_dash|max:40','name'=>'required|string|max:200','budget_amount'=>'nullable|numeric|min:0','starts_on'=>'nullable|date','ends_on'=>'nullable|date|after_or_equal:starts_on']);abort_unless($a->allows($r->user(),$t,'projects.manage',$d['company_id']),403);abort_unless(Company::where('tenant_id',$t)->whereKey($d['company_id'])->exists(),404);return response()->json(['data'=>Project::create([...$d,'tenant_id'=>$t])],201);} public function task(Request $r,Project $project,OptionalModuleService $m,AuthorizationService $a){$m->require('projects');$t=app(TenantContext::class)->id();abort_unless($project->tenant_id===$t,404);abort_unless($a->allows($r->user(),$t,'projects.manage',$project->company_id),403);$d=$r->validate(['milestone_id'=>'nullable|uuid','assignee_id'=>'nullable|uuid','title'=>'required|string|max:200','estimated_hours'=>'nullable|numeric|min:0']);return response()->json(['data'=>ProjectTask::create([...$d,'tenant_id'=>$t,'project_id'=>$project->id])],201);} public function timesheet(Request $r,Project $project,OptionalModuleService $m,AuthorizationService $a){$m->require('projects');$t=app(TenantContext::class)->id();abort_unless($project->tenant_id===$t,404);abort_unless($a->allows($r->user(),$t,'projects.time'),403);$d=$r->validate(['task_id'=>'nullable|uuid','employee_id'=>'required|uuid','work_date'=>'required|date','hours'=>'required|numeric|gt:0','description'=>'nullable|string']);abort_unless(Employee::where('tenant_id',$t)->where('company_id',$project->company_id)->whereKey($d['employee_id'])->exists(),404);return response()->json(['data'=>ProjectTimesheet::create([...$d,'tenant_id'=>$t,'project_id'=>$project->id])],201);} }
